import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, uv, mix, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create plane geometry (card-like proportions)
  const geometry = new THREE.PlaneGeometry(1.2, 0.75);

  // Load the brushed metal texture
  const material = new MeshBasicNodeMaterial();
  material.colorNode = color(0xffffff);

  // Apply texture if imageUrl exists
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      material.colorNode = texture;
      material.needsUpdate = true;
    });
  }

  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene position/rotation/scale
  if (config.scenePosition) {
    mesh.position.set(
      config.scenePosition.x || 0,
      config.scenePosition.y || 0,
      config.scenePosition.z || 0
    );
  }

  if (config.sceneRotation) {
    mesh.rotation.set(
      config.sceneRotation.x || 0,
      config.sceneRotation.y || 0,
      config.sceneRotation.z || 0
    );
  }

  if (config.sceneScale) {
    mesh.scale.set(
      config.sceneScale.x || 1,
      config.sceneScale.y || 1,
      config.sceneScale.z || 1
    );
  }

  // Add text label ("Journal 1")
  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textItem = textContent.find(item => item.role === 'headline') || textContent[0];

  if (textItem && textItem.text) {
    const textMesh = ctx.fontAtlas.createText(textItem.text, {
      fontSize: textItem.typography?.fontSize || 39,
      color: '#e8ecf2',
      align: 'center'
    });

    // Position text above/on the plane
    textMesh.position.z = 0.1;
    textMesh.position.y = 0.15;
    mesh.add(textMesh);
  }

  // Setup cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  mesh.userData.handlers = {};

  return mesh;
}
